<script setup lang="ts">
import {useNativeCard} from '../../business/controller';
const {readonly,plan,receipt,busy,edited,commitAllowed,labels,planLabels,planStates,checkText,period,perform,refresh,commit,reject}=useNativeCard();
</script>
<template>
   <div v-if="plan" class="native-confirm"><b>{{planLabels[plan.kind]||'业务办理'}} · {{plan.id}} · v{{plan.version}}</b><p>业务状态：{{planStates[plan.state]||plan.state}} · 有效期 {{plan.expiresAt}}</p><p v-if="plan.payload.candidate">目标：{{plan.payload.candidate.roomName}} · {{period(plan.payload.candidate.periodKey)}} · {{plan.payload.date}}</p><p>{{plan.payload.reason||plan.payload.description||plan.payload.note||plan.payload.title}}</p><p v-if="plan.payload.nextStatus">将工单改为 {{labels[plan.payload.nextStatus]||plan.payload.nextStatus}}</p><p v-if="plan.payload.checklist">{{checkText(plan.payload.checklist)}} · {{plan.payload.finalize?'最终交接待接收':'检查登记可继续补全'}}</p><p v-if="plan.payload.audience">通知对象：{{plan.payload.audience.className||plan.payload.audience.role||'全体用户'}}</p><p v-if="edited&&!receipt">条件已修改，请重新准备后确认。</p><div class="button-row" v-if="!readonly"><button data-native-confirm :disabled="!commitAllowed" @click="commit">本人确认提交到原系统</button><button :disabled="!commitAllowed" @click="reject">拒绝方案</button><button :disabled="busy" @click="perform(refresh)">回查 / 恢复状态</button></div></div>
   <div v-if="receipt" class="native-receipt"><b>✓ 原系统回执 {{receipt.operationId}}</b><p>{{receipt.committedAt}} · {{receipt.objects.map(o=>o.kind+':'+o.id).join('、')}}</p><p>同方案重试回查相同编号。请查询最新安排或对象状态确认实际结果。</p><button :disabled="busy" @click="perform(refresh)">回查同编号与最新对象</button></div>
</template>
